  "CH4 酸滴定：甲基黃（Methyl yellow）2.9–4.0（醇）；★甲基橙（{{Methyl orange|物質}}）3.2–4.4（水）[111-2]；甲基紅（Methyl red）4.2–6.2（NaOH＋水）；顏色變化{{紅-黃|顏色}} [110-1]",
  "CH5 鹼滴定：溴瑞香酚藍（Bromothymol blue, BTB）6.0–7.6 {{黃-藍|顏色}}；瑞香酚酞（Thymolphthalein）9.3–10.5 無-藍（醇）",
  "CH5 鹼滴定：★酚酞（{{Phenolphthalein|物質}}, PP）{{8.3–10|數值}}，{{無-紅|顏色}}（醇）[108-1、112-2、107-2]",
  "CH6 非水滴定（酸）：結晶紫（{{Crystal violet|物質}}）2.0–0.5 紫-綠",
