  "指示劑 {{酚酞|物質}}（8.3~10，無 → 紅）：2NaOH ＋ H₂SO₄ → Na₂SO₄ ＋ 2H₂O；↓ 吸收 CO₂：2Na₂CO₃（含量不得超過 {{3%|數值}}）＋ H₂SO₄ → 2NaHCO₃ ＋ Na₂SO₄",
  "指示劑 {{甲基橙|物質}} [96-2]：2NaHCO₃ ＋ H₂SO₄ → Na₂SO₄ ＋ 2H₂O ＋ 2CO₂"
