  "分析：測定{{碘液|物質}}：KAsO₂ ＋ I₂ ＋ 2H₂O → KH₂AsO₄ ＋ 2HI",
  "以{{澱粉|物質}}為指示劑，維持鹼性以{{碳酸氫鉀|物質}}（KHCO₃）為緩衝試劑，中和生成的氫碘酸 HI 使反應快速 [93-2]"
