  "{{Nernst's distribution law|名詞}}：{{少量多次|名詞}}（每次 {{10~20ml|數值}}）反覆抽提生物鹼之效果較一次性抽提為佳",
  "生物鹼：易溶於{{有機溶劑|名詞}}（醚、氯仿、四氯化碳），僅微溶於水（大多會沉澱）",
