  "Vit B₂（螢光測定）：Vit. B₂ ＋ Sodium Hydrosulfite（{{低亞硫酸鈉|物質}} Na₂S₂O₄）→ 使{{螢光消失|名詞}}",
  "Vit B₆：{{Gibb's reaction|名詞}}：以 2,6-dichloroquinone chloroimide 呈色（＋ 水 → {{瞬藍後紅|顏色}}／＋ 飽和硼酸液 → 不呈色）[95-2]",
