  "適用：含{{硫醇|結構}}（thiol）：penicillamine、captopril；{{易氧化|性質}} [103-1、100-2]：Catecholamine（DA/NE/Epi）、Vit C",
  "特點：靈敏性{{高|性質}} [111-1]；可低於 ng"
