  "{{微波誘導之電漿原子發散|名詞}} MIP-AES：微波加熱至 > {{6000°C|數值}} 產生 {{Ar|物質}} 電熱漿，所有元素會產生發散光譜 → 用 DAD 偵測（原理似 ICP-AES 詳見第 31-3 頁）；適用：各別元素（有機氯殺蟲劑、有機金屬中的金屬）；廣泛用於檢測藥品不純物及代謝研究；pg",
