  "{{真空連通管|名詞}}（vacuum manifold）可用於同時執行多件萃取",
  "新技術連線－{{限制進樣介質|名詞}}（restricted access media, RAM）：使親脂藥物進入，{{蛋白質分子過大|名詞}}而被排出"
