  "Conditioning solvent：{{活化管柱|名詞}}，使管柱內平衡再進行分析；先用 {{5~10 倍|數值}}的充填床體積之沖提液（Eluting solvent）沖洗",
  "Sample loading：將樣品用適當溶劑溶入並注入管柱",
