  "★{{親脂性矽膠|物質}}（逆相）：以{{凡德瓦爾力|名詞}}（Van der Waals）滯留非極性的物質（如：固醇類 {{hydrocortisone|藥名}}）",
  "親脂性矽膠：{{polydimethylsiloxane|物質}} 為常用的親脂性 SPME 吸附材質 [111-2、103-2]；檢品裝載容積比樹脂{{小|性質}} [102-1]",
  "⚠ {{silica gel|物質}} 在{{強鹼|名詞}}下不安定 [考爆]",
