  "{{前驅離子掃描|名詞}}（Precursor ion）：Q1 掃描 全範圍；Q3 固定 選定碎片；偵測{{共享某碎片的母離子族群|名詞}}",
  "{{中性丟失掃描|名詞}}（Neutral loss）：Q1 掃描 全範圍；Q3 掃描 同步 Δm；偵測{{共同中性丟失的化合物族群|名詞}}",
  "{{多重反應監測|名詞}}（MRM／SRM）：Q1 固定 選定母離子；Q3 固定 選定碎片；{{定量首選|名詞}}，{{靈敏度最高|性質}}",
  "＊MRM（multiple reaction monitoring）：循環監測{{多組|名詞}} transition（不只一組 precursor → product），整體分析專一性較高，{{臨床藥物監測|名詞}}常用",
  "＊SRM（selected reaction monitoring）：只監測{{單一|名詞}} transition（一組 precursor → product）"
