  "★波長★：約 780~10⁶ nm [106-1、104-2、104-1、102-1]：近紅外光 {{0.8~2.5 μm|數值}}（12500~4000cm⁻¹）；中紅外光 {{2.5~50 μm|數值}}（4000~200 cm⁻¹）；遠紅外光 50~1000 μm（200~10 cm⁻¹）",
