  "光源：① {{中空陰極燈|名詞}}專門發射{{目標元素|名詞}}的特定波長：測量{{總吸收值|名詞}}",
  "光源：② {{重氫燈（D₂）|物質}}提供連續的光譜：測量{{背景|名詞}}吸收值"
