  "能階分配 [102-2、91-1]：逆向（高能階）／順向（低能階）＝ N_H／N_L ＝ N₋₁/₂／N₊₁/₂ ＝ {{e^（−ΔE／KT）|名詞}}（ΔE：能階差；K：{{Boltzmann constant|名詞}}（1.38 × 10⁻²³ J/K ＝ 1.38 × 10⁻¹⁶ erg/K）；T：絕對溫度（273＋°C））",
