  "成因：{{電子雲遮蔽作用|名詞}} shielding effect：電子繞著原子核旋轉，形成與外加磁場反向的磁場，而抵銷外加磁場的強度 → 原子實際感受的磁場強度，與外加磁場強度有所差異"
