  "{{去活化基|名詞}}（拉電子基）→ 使 H 化學位移 δ {{變大|性質}}：強：{{-NO₂ -COOH -COOR|結構}}；中：-NH₃⁺；弱：-Cl（放在間／對位時為例外，δ 反而會變小）；Ho → δ 變大大大，Hp → δ 變大大，Hm → δ 變大",
